args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?birthDate WHERE {
  VALUES ?person { dbr:Bojan_Bazelli dbr:Alireza_Afzal }
  OPTIONAL { ?person dbo:birthDate ?dob1 . }
  OPTIONAL { ?person dbp:birthDate ?dob2 . }
  OPTIONAL { ?person dbp:birth_date ?dob3 . }
  OPTIONAL { ?person dbp:born ?dob4 . }
  BIND (COALESCE(?dob1, ?dob2, ?dob3, ?dob4) AS ?birthDate)
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER (lang(?personLabel) = "en") }
  FILTER(bound(?birthDate))
}
ORDER BY ?birthDate

